{
  "root": "main_stack",
  "state": {
    "itineraryDays": [
      {
        "dayDate": "Day 1: November 8, 2024",
        "morningActivity": "Arrive in Kyoto, check into accommodation.",
        "afternoonActivity": "Explore Arashiyama Bamboo Grove, Tenryu-ji Temple, and Togetsukyo Bridge.",
        "eveningActivity": "Dinner in Arashiyama, enjoy local specialties."
      },
      {
        "dayDate": "Day 2: November 9, 2024",
        "morningActivity": "Visit Fushimi Inari Shrine (Torii gates).",
        "afternoonActivity": "Explore Gion district, Kiyomizu-dera Temple.",
        "eveningActivity": "Traditional Kaiseki dinner in Gion."
      },
      {
        "dayDate": "Day 3: November 10, 2024",
        "morningActivity": "Visit Kinkaku-ji (Golden Pavilion) and Ryoan-ji Temple (Zen garden).",
        "afternoonActivity": "Souvenir shopping near Kyoto Station, enjoy a final Japanese lunch.",
        "eveningActivity": "Depart from Kyoto."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "intro_text",
        "itinerary_h2",
        "itinerary_table",
        "quick_actions_h3",
        "quick_actions_stack",
        "sources_h3",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Kyoto Autumn Cultural Escape (November 8-10, 2024)",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This 3-day itinerary for two adults focuses on Kyoto's rich cultural heritage and traditional Japanese cuisine, set against the beautiful autumn backdrop. The plan is designed to fit a moderate budget of approximately $1000 USD for activities and food, excluding flights and accommodation.",
        "variant": "body"
      },
      "children": []
    },
    "itinerary_h2": {
      "type": "Text",
      "props": {
        "text": "Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "dayDate",
            "label": "Day"
          },
          {
            "key": "morningActivity",
            "label": "Morning"
          },
          {
            "key": "afternoonActivity",
            "label": "Afternoon"
          },
          {
            "key": "eveningActivity",
            "label": "Evening"
          }
        ],
        "statePath": "/itineraryDays",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayDate",
        "highlightColumns": [
          "morningActivity",
          "afternoonActivity"
        ]
      },
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "book_accommodation_button",
        "explore_tours_button"
      ]
    },
    "book_accommodation_button": {
      "type": "Button",
      "props": {
        "label": "Book Accommodation"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/kyoto-hotels"
          }
        }
      }
    },
    "explore_tours_button": {
      "type": "Button",
      "props": {
        "label": "Explore Local Tours"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/kyoto-tours"
          }
        }
      }
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "kyoto_tourism_button",
        "japan_guide_button"
      ]
    },
    "kyoto_tourism_button": {
      "type": "Button",
      "props": {
        "label": "Kyoto Official Tourism"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://kyoto.travel/en/"
          }
        }
      }
    },
    "japan_guide_button": {
      "type": "Button",
      "props": {
        "label": "Japan Guide"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.japan-guide.com/e/e2158.html"
          }
        }
      }
    }
  }
}
